import React, { useState } from 'react';
import Navbar from './components/Navbar';
import Home from './components/Home';
import Timetable from './components/Timetable';
import Teachers from './components/Teachers';
import About from './components/About';
import LmsDashboard from './components/LmsDashboard'; // Admin
import StudentDashboard from './components/StudentDashboard';
import TeacherDashboard from './components/TeacherDashboard';
import Footer from './components/Footer';
import Login from './components/Login';

export default function App() {
  const [currentPage, setCurrentPage] = useState('Home');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userRole, setUserRole] = useState(null); // Role එක මතක තියාගන්න
  const [studentName, setStudentName] = useState('User');

  const handleLoginSubmit = async (username, password) => {
    try {
      const response = await fetch('http://localhost:8081/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, password })
      });
      const data = await response.json();
      
      if (data.status === 'Success') {
        setIsLoggedIn(true);
        setShowLoginModal(false);
        setUserRole(data.role); // Backend එකෙන් එන role එක (Admin/Teacher/Student)
        setStudentName(data.name);
        
        // Role එක අනුව පිටුව තීරණය කරන්න
        if (data.role === 'Admin') setCurrentPage('Dashboard');
        else if (data.role === 'Teacher') setCurrentPage('TeacherDashboard');
        else setCurrentPage('StudentDashboard');
      } else {
        alert('Invalid Username or Password!');
      }
    } catch (error) {
      alert('Backend Server එක Run වෙන්නේ නැහැ මචං!');
    }
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setUserRole(null);
    setCurrentPage('Home');
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', minHeight: '100vh', backgroundColor: '#f8fafc' }}>
      
      {/* ඔයාගේ මුල් Navbar එක හැමතැනම පේනවා */}
      <Navbar 
         onLoginClick={() => setShowLoginModal(true)} 
         isLoggedIn={isLoggedIn} 
         studentName={studentName}
         setCurrentPage={setCurrentPage} 
         currentPage={currentPage}
      />

      <main style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
        {currentPage === 'Home' && <Home />}
        {currentPage === 'Classes' && <Timetable setCurrentPage={setCurrentPage} />}
        {currentPage === 'Teachers' && <Teachers />}
        {currentPage === 'About' && <About />}
        
        {/* Role එක අනුව Dashboard එක පේනවා */}
        {isLoggedIn && currentPage === 'Dashboard' && <LmsDashboard handleLogout={handleLogout} />}
        {isLoggedIn && currentPage === 'TeacherDashboard' && <TeacherDashboard teacherData={{name: studentName}} />}
        {isLoggedIn && currentPage === 'StudentDashboard' && <StudentDashboard studentData={{name: studentName}} />}
      </main>

      <Footer />

      {showLoginModal && (
        <Login setShowLoginModal={setShowLoginModal} handleLoginSubmit={handleLoginSubmit} />
      )}
    </div>
  );
}
